import { Task } from '../entities/Task';
import { ValidationError } from '../errors/DomainError';
import { UserRepository } from '../repositories/UserRepository';

/** Enforces that only existing users can be assigned to a task. */
export class TaskAssignmentService {
  constructor(private readonly users: Pick<UserRepository, 'findById'>) {}

  async assign(task: Task, userId: string): Promise<void> {
    const user = await this.users.findById(userId);
    if (user === null) {
      throw new ValidationError(`User "${userId}" does not exist and cannot be assigned`);
    }
    task.assignTo(user.id);
  }
}

